package com.asmj.marketplace.jobs;
import com.asmj.marketplace.model.UserAccount; import com.asmj.marketplace.repository.UserAccountRepository; import com.asmj.marketplace.service.CloudinaryImageService; import org.springframework.web.multipart.MultipartFile;
import java.time.Instant; import java.util.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import org.springframework.security.core.Authentication;
@Controller
public class JobMarketplaceController {
 private final EmployerProfileRepository employers; private final JobPostingRepository jobs; private final JobApplicationRepository applications; private final UserAccountRepository users; private final CloudinaryImageService cloudinary;
 public JobMarketplaceController(EmployerProfileRepository e,JobPostingRepository j,JobApplicationRepository a,UserAccountRepository u,CloudinaryImageService c){employers=e;jobs=j;applications=a;users=u;cloudinary=c;}
 private UserAccount user(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 private EmployerProfile employer(Authentication a){return employers.findByUserId(user(a).getId()).orElse(null);}
 private String clean(String v,int n){if(v==null)return "";v=v.trim();return v.length()>n?v.substring(0,n):v;}
 @GetMapping("/jobs") public String browse(@RequestParam(required=false) String q,@RequestParam(required=false) String city,Model m){List<JobPosting> list=jobs.findByStatusOrderByCreatedAtDesc("PUBLISHED"); if(q!=null&&!q.isBlank())list.removeIf(j->!(j.getTitle()+" "+j.getSkills()+" "+j.getOrganisationName()).toLowerCase().contains(q.trim().toLowerCase())); if(city!=null&&!city.isBlank())list.removeIf(j->j.getCity()==null||!j.getCity().equalsIgnoreCase(city.trim())); m.addAttribute("jobs",list);m.addAttribute("q",q);m.addAttribute("city",city);return "jobs/list";}
 @GetMapping("/jobs/{id}") public String detail(@PathVariable String id,Model m){JobPosting j=jobs.findById(id).orElse(null);if(j==null||!"PUBLISHED".equals(j.getStatus()))return "error";m.addAttribute("job",j);return "jobs/detail";}
 @PostMapping("/jobs/{id}/apply") public String apply(@PathVariable String id,@RequestParam("resume") MultipartFile resume,@RequestParam(required=false) String coverLetter,Authentication a,RedirectAttributes ra){JobPosting j=jobs.findById(id).orElse(null);if(j==null||!"PUBLISHED".equals(j.getStatus())){ra.addFlashAttribute("error","This vacancy is no longer accepting applications.");return "redirect:/jobs";}UserAccount u=user(a);if(applications.existsByJobIdAndCandidateUserId(id,u.getId())){ra.addFlashAttribute("error","You have already applied for this vacancy.");return "redirect:/jobs/"+id;}String resumeUrl;try{Map<String,Object> uploaded=cloudinary.uploadDocument(resume,"asmj-shoppe/jobs/resumes");resumeUrl=String.valueOf(uploaded.get("secure_url"));}catch(RuntimeException ex){ra.addFlashAttribute("error",ex.getMessage());return "redirect:/jobs/"+id;}JobApplication x=new JobApplication();x.setJobId(id);x.setCandidateUserId(u.getId());x.setCandidateName(u.getFullName());x.setCandidateEmail(u.getEmail());x.setCandidateMobile(u.getMobile());x.setResumeUrl(clean(resumeUrl,1000));x.setCoverLetter(clean(coverLetter,3000));applications.save(x);ra.addFlashAttribute("success","Application submitted. You can track it from My job applications.");return "redirect:/candidate/job-applications";}
 @GetMapping("/candidate/job-applications") public String candidateApps(Authentication a,Model m){m.addAttribute("applications",applications.findByCandidateUserIdOrderByCreatedAtDesc(user(a).getId()));m.addAttribute("jobs",jobs.findAll().stream().collect(java.util.stream.Collectors.toMap(JobPosting::getId,j->j,(x,y)->x)));return "jobs/candidate-applications";}
 @GetMapping("/employer/register") public String employerRegister(Authentication a,Model m){EmployerProfile p=employer(a);m.addAttribute("profile",p==null?new EmployerProfile():p);return "jobs/employer-register";}
 @PostMapping("/employer/register") public String saveEmployer(@ModelAttribute EmployerProfile form,Authentication a,RedirectAttributes ra){UserAccount u=user(a);EmployerProfile p=employer(a);if(p==null)p=new EmployerProfile();p.setUserId(u.getId());p.setOwnerName(clean(u.getFullName(),100));p.setEmail(u.getEmail());p.setMobile(u.getMobile());p.setOrganisationName(clean(form.getOrganisationName(),160));p.setOrganisationType(clean(form.getOrganisationType(),50));p.setWebsite(clean(form.getWebsite(),250));p.setDescription(clean(form.getDescription(),2000));p.setAddress(clean(form.getAddress(),250));p.setCity(clean(form.getCity(),80));p.setState(clean(form.getState(),80));p.setPinCode(clean(form.getPinCode(),10));if(p.getOrganisationName().isBlank()||p.getCity().isBlank()||p.getState().isBlank()){ra.addFlashAttribute("error","Organisation name, city and state are required.");return "redirect:/employer/register";}p.setStatus("PENDING");p.setAdminNote(null);employers.save(p);ra.addFlashAttribute("success","Employer verification request submitted. Job posting is enabled after admin approval.");return "redirect:/employer/register";}
 @GetMapping("/employer/dashboard") public String employerDashboard(Authentication a,Model m){EmployerProfile p=employer(a);m.addAttribute("profile",p);m.addAttribute("jobs",p==null?List.of():jobs.findByEmployerUserIdOrderByCreatedAtDesc(user(a).getId()));m.addAttribute("applications",p==null?List.of():applications.findAll().stream().filter(x->jobs.findById(x.getJobId()).map(j->j.getEmployerUserId().equals(user(a).getId())).orElse(false)).toList());return "jobs/employer-dashboard";}
 @GetMapping("/employer/jobs/new") public String newJob(Authentication a,Model m,RedirectAttributes ra){EmployerProfile p=employer(a);if(p==null||!"APPROVED".equals(p.getStatus())){ra.addFlashAttribute("error","Complete employer registration and wait for admin approval before posting jobs.");return "redirect:/employer/register";}m.addAttribute("job",new JobPosting());return "jobs/job-form";}
 @PostMapping("/employer/jobs") public String saveJob(@ModelAttribute JobPosting form,Authentication a,RedirectAttributes ra){EmployerProfile p=employer(a);if(p==null||!"APPROVED".equals(p.getStatus()))return "redirect:/employer/register";if(clean(form.getTitle(),150).isBlank()||clean(form.getDescription(),5000).isBlank()||clean(form.getCity(),80).isBlank()){ra.addFlashAttribute("error","Job title, description and city are required.");return "redirect:/employer/jobs/new";}form.setId(null);form.setEmployerProfileId(p.getId());form.setEmployerUserId(p.getUserId());form.setOrganisationName(p.getOrganisationName());form.setTitle(clean(form.getTitle(),150));form.setDepartment(clean(form.getDepartment(),100));form.setDescription(clean(form.getDescription(),5000));form.setResponsibilities(clean(form.getResponsibilities(),3000));form.setQualifications(clean(form.getQualifications(),2000));form.setSkills(clean(form.getSkills(),500));form.setExperience(clean(form.getExperience(),80));form.setCity(clean(form.getCity(),80));form.setState(clean(form.getState(),80));form.setPinCode(clean(form.getPinCode(),10));form.setApplicationEmail(p.getEmail());form.setStatus("PENDING");form.setCreatedAt(Instant.now());form.setUpdatedAt(Instant.now());jobs.save(form);ra.addFlashAttribute("success","Job submitted for admin review. It will appear publicly after approval.");return "redirect:/employer/dashboard";}
 @GetMapping("/employer/jobs/{id}/applications") public String jobApplications(@PathVariable String id,Authentication a,Model m){JobPosting j=jobs.findById(id).orElse(null);if(j==null||!j.getEmployerUserId().equals(user(a).getId()))return "error";m.addAttribute("job",j);m.addAttribute("applications",applications.findByJobIdOrderByCreatedAtDesc(id));return "jobs/employer-applications";}
 @PostMapping("/employer/applications/{id}/status") public String updateApplication(@PathVariable String id,@RequestParam String status,@RequestParam(required=false) String notes,Authentication a,RedirectAttributes ra){JobApplication x=applications.findById(id).orElse(null);if(x==null)return "error";JobPosting j=jobs.findById(x.getJobId()).orElse(null);if(j==null||!j.getEmployerUserId().equals(user(a).getId()))return "error";if(!Set.of("UNDER_REVIEW","SHORTLISTED","REJECTED","SELECTED","OFFERED","OFFER_ACCEPTED").contains(status)){ra.addFlashAttribute("error","Invalid application status.");return "redirect:/employer/jobs/"+x.getJobId()+"/applications";}x.setStatus(status);x.setEmployerNotes(clean(notes,2000));x.setUpdatedAt(Instant.now());applications.save(x);ra.addFlashAttribute("success","Candidate application updated.");return "redirect:/employer/jobs/"+x.getJobId()+"/applications";}
 @PostMapping("/employer/applications/{id}/interview") public String scheduleInterview(@PathVariable String id,@ModelAttribute JobApplication.InterviewRound round,Authentication a,RedirectAttributes ra){JobApplication x=applications.findById(id).orElse(null);if(x==null)return "error";JobPosting j=jobs.findById(x.getJobId()).orElse(null);if(j==null||!j.getEmployerUserId().equals(user(a).getId()))return "error";if(round.getRoundName()==null||round.getRoundName().isBlank()||round.getScheduledAt()==null){ra.addFlashAttribute("error","Interview round and date/time are required.");return "redirect:/employer/jobs/"+x.getJobId()+"/applications";}round.setRoundName(clean(round.getRoundName(),80));round.setMode(clean(round.getMode(),20));round.setMeetingLink(clean(round.getMeetingLink(),500));round.setLocation(clean(round.getLocation(),250));round.setInterviewer(clean(round.getInterviewer(),120));round.setResult("SCHEDULED");x.getInterviews().add(round);x.setStatus("INTERVIEW_SCHEDULED");x.setUpdatedAt(Instant.now());applications.save(x);ra.addFlashAttribute("success","Interview round scheduled.");return "redirect:/employer/jobs/"+x.getJobId()+"/applications";}
 @PostMapping("/employer/applications/{id}/offer-letter") public String uploadOfferLetter(@PathVariable String id,@RequestParam("offerLetter") MultipartFile offerLetter,Authentication a,RedirectAttributes ra){JobApplication x=applications.findById(id).orElse(null);if(x==null)return "error";JobPosting j=jobs.findById(x.getJobId()).orElse(null);if(j==null||!j.getEmployerUserId().equals(user(a).getId()))return "error";try{Map<String,Object> uploaded=cloudinary.uploadDocument(offerLetter,"asmj-shoppe/jobs/offer-letters");x.setOfferLetterUrl(clean(String.valueOf(uploaded.get("secure_url")),1000));x.setStatus("OFFERED");x.setUpdatedAt(Instant.now());applications.save(x);ra.addFlashAttribute("success","Offer letter uploaded and candidate status updated to OFFERED.");}catch(RuntimeException ex){ra.addFlashAttribute("error",ex.getMessage());}return "redirect:/employer/jobs/"+x.getJobId()+"/applications";}
 @PostMapping("/employer/applications/{id}/interview-feedback") public String feedback(@PathVariable String id,@RequestParam int roundIndex,@RequestParam String feedback,@RequestParam String result,Authentication a,RedirectAttributes ra){JobApplication x=applications.findById(id).orElse(null);if(x==null)return "error";JobPosting j=jobs.findById(x.getJobId()).orElse(null);if(j==null||!j.getEmployerUserId().equals(user(a).getId())||roundIndex<0||roundIndex>=x.getInterviews().size())return "error";if(!Set.of("PASSED","FAILED","PENDING").contains(result))return "error";JobApplication.InterviewRound r=x.getInterviews().get(roundIndex);r.setFeedback(clean(feedback,2000));r.setResult(result);x.setUpdatedAt(Instant.now());applications.save(x);ra.addFlashAttribute("success","Interview feedback saved.");return "redirect:/employer/jobs/"+x.getJobId()+"/applications";}
 @GetMapping("/admin/jobs") public String adminJobs(Model m){m.addAttribute("employers",employers.findAllByOrderByCreatedAtDesc());m.addAttribute("jobs",jobs.findAllByOrderByCreatedAtDesc());return "jobs/admin";}
 @PostMapping("/admin/jobs/employers/{id}/status") public String employerStatus(@PathVariable String id,@RequestParam String status,@RequestParam(required=false) String note,RedirectAttributes ra){EmployerProfile p=employers.findById(id).orElse(null);if(p==null)return "error";if(!Set.of("APPROVED","REJECTED","SUSPENDED").contains(status))return "error";p.setStatus(status);p.setAdminNote(clean(note,1000));p.setReviewedAt(Instant.now());employers.save(p);ra.addFlashAttribute("success","Employer status updated.");return "redirect:/admin/jobs";}
 @PostMapping("/admin/jobs/{id}/status") public String jobStatus(@PathVariable String id,@RequestParam String status,@RequestParam(required=false) String note,RedirectAttributes ra){JobPosting j=jobs.findById(id).orElse(null);if(j==null)return "error";if(!Set.of("PUBLISHED","REJECTED","CLOSED").contains(status))return "error";j.setStatus(status);j.setAdminNote(clean(note,1000));j.setUpdatedAt(Instant.now());jobs.save(j);ra.addFlashAttribute("success","Job posting status updated.");return "redirect:/admin/jobs";}
}
